"""
    Checks if n is a prime number
    Returns: boolean (True if n is prime, False otherwise)
    """
def is_prime(n: Any) -> object {
    if (n < 2) {
        return False;
    }
    if (n == 2) {
        return True;
    }
    if ((n % 2) == 0) {
        return False;
    }
    for x in range(3, (int((n ** 0.5)) + 1), 2) {
        if ((n % x) == 0) {
            return False;
        }
    }
    return True;
}

"""
    calculates the antipode of list of directions
    """
def doreverse_list(decs: Any, incs: Any) -> object {
    incs_flipped = [-i for i in incs];
    decs_flipped = [((dec + 180.0) % 360.0) for dec in decs];
    return (decs_flipped, incs_flipped);
}

"""splituser('user[:passwd]@host[:port]') --> 'user[:passwd]', 'host[:port]'."""
def splituser(host: Any) -> object {
    (user, delim, host) = host.rpartition('@');
    return (user if delim else None, host);
}

"""
    Check if number is Armstrong number
    """
def armstrong_number(number: Any) -> object {
    calc = number;
    sum_ = 0;
    while (calc > 0) {
        dig = calc % 10;
        sum_ += dig ** 3;
        calc //= 10;
    }
    if (number == sum_) {
        return True;
    } else {
        return False;
    }
}

